        "viz_card_06_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_06"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> primary | seriesByName(\"WindowPathChanges\") | lastPoint() | divideBy(0.999999999999)",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "absolute",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"BucketPathChanges\")",
                "trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#4cbf7f",
                        "to": -0.000001
                    },
                    {
                        "value": "#a6adb6",
                        "from": -0.000001,
                        "to": 0.000001
                    },
                    {
                        "value": "#f7782f",
                        "from": 0.000001
                    }
                ]
            }
        },
